function closeAsPageOverlays(){document.querySelectorAll(`.overlay.as-page.open`).forEach(el=>closeOverlay(el.id))}window.addEventListener(`hashchange`,closeAsPageOverlays);function syncAppHeaderHeight(){const header=document.querySelector(`header`);if(!header)return;document.documentElement.style.setProperty(`--app-header-h`,`${Math.round(header.getBoundingClientRect().height)}px`)}if(typeof ResizeObserver===`function`){const headerEl=document.querySelector(`header`);if(headerEl)new ResizeObserver(syncAppHeaderHeight).observe(headerEl)}syncAppHeaderHeight();function profilePageFriendCount(){return typeof friendships!==`undefined`&&Array.isArray(friendships)?friendships.filter(f=>f.status===`accepted`).length:0}function ppPlural(n,word){return`${n} ${word}${n>1?`s`:``}`}function renderProfilePageHead(){const name=currentProfile&&currentProfile.display_name||currentUser&&currentUser.email||``;document.getElementById(`ppName`).textContent=name;const shows=typeof trackedShows!==`undefined`&&Array.isArray(trackedShows)?trackedShows.length:0;document.getElementById(`ppSub`).textContent=[ppPlural(films.length,`film`),ppPlural(shows,`série`),ppPlural(profilePageFriendCount(),`ami`)].join(` · `);const img=document.getElementById(`ppAvatarImg`);const fallback=document.getElementById(`ppAvatarFallback`);const avatarUrl=currentProfile&&currentProfile.avatar_url;if(avatarUrl){img.src=avatarUrl;img.style.display=``;fallback.style.display=`none`}else{img.style.display=`none`;fallback.style.display=``}}function renderProfilePageFigures(){const s=computeStats(films);const figures=[[String(s.rated),`Films notés`],[s.avg!==null?s.avg.toFixed(1):`—`,`Note moyenne`],[String(s.favCount),`Favoris`],[rythmeAnnuel(s),`Films par mois`]];document.getElementById(`ppFigures`).innerHTML=figures.map(([value,label])=>`
    <div class="pp-figure"><b>${escapeHtml(value)}</b><span>${label}</span></div>
  `).join(``)}function renderProfilePageFavs(){const wrap=document.getElementById(`ppFavs`);const ids=currentProfile&&Array.isArray(currentProfile.top_films)?currentProfile.top_films:[];const picked=ids.map(id=>films.find(f=>f.tmdbId===id)).filter(Boolean);if(picked.length===0){wrap.innerHTML=`<button type="button" class="pp-favs-empty" id="ppFavsPickBtn">Choisis tes 4 films préférés</button>`;document.getElementById(`ppFavsPickBtn`).addEventListener(`click`,openProfileModal);return}const navList=picked.map(f=>({tmdbId:f.tmdbId,title:f.title}));wrap.innerHTML=picked.map(f=>`
    <button type="button" class="pp-fav" data-tmdb-id="${f.tmdbId}" aria-label="${escapeHtml(f.title)}">
      ${f.posterUrl?`<img class="pp-fav-poster" src="${escapeHtml(f.posterUrl)}" alt="" loading="lazy" decoding="async">`:`<span class="pp-fav-poster film-poster-placeholder">${FILM_PLACEHOLDER_SVG}</span>`}
      <span class="pp-fav-title">${escapeHtml(f.title)}</span>
    </button>
  `).join(``);wrap.querySelectorAll(`.pp-fav`).forEach(btn=>{btn.addEventListener(`click`,()=>goToFilmDetail(parseInt(btn.dataset.tmdbId,10),navList))})}function renderProfilePageRows(){document.getElementById(`ppRecapLabel`).textContent=`Ton année ${new Date().getFullYear()}`;const a=computeAchievements();document.getElementById(`ppAchVal`).textContent=`${a.tiersUnlocked+a.hiddenUnlocked} / ${a.tiersTotal+a.hiddenTotal}`;document.getElementById(`ppTcgBadge`).hidden=true;const changelogLink=document.getElementById(`profileChangelogLinkBtn`);document.getElementById(`ppChangelogRow`).hidden=!changelogLink||changelogLink.style.display===`none`;document.getElementById(`ppAdminRow`).hidden=!(typeof isAdmin===`function`&&isAdmin());const isPublic=!!(currentProfile&&currentProfile.public_profile);document.getElementById(`ppPublicToggle`).checked=isPublic;renderProfileShareNote()}function renderProfilePage(){if(!currentUser)return;renderProfilePageHead();renderProfilePageFigures();renderProfilePageFavs();renderProfilePageRows()}function refreshProfilePageCards(){if(typeof refreshAlbumCount===`function`)refreshAlbumCount()}async function openProfilePage(){renderProfilePage();await Promise.all([typeof loadTrackedShows===`function`?loadTrackedShows():Promise.resolve(),typeof loadFriendships===`function`?loadFriendships():Promise.resolve()]).catch(e=>console.error(e));if(parseRoute().name!==`profil`)return;renderProfilePage();refreshProfilePageCards();if(typeof refreshAvisBadge===`function`)refreshAvisBadge().catch(e=>console.error(e));if(typeof refreshAdminCounts===`function`)refreshAdminCounts().catch(e=>console.error(e))}document.getElementById(`profilePage`).addEventListener(`click`,e=>{const row=e.target.closest(`[data-proxy]`);if(!row)return;const target=document.getElementById(row.dataset.proxy);if(target)target.click()});document.getElementById(`ppEditBtn`).addEventListener(`click`,openProfileModal);document.getElementById(`ppRecapBtn`).addEventListener(`click`,openYearRecap);async function savePublicProfile(on){if(blockIfOffline())return false;const{data,error}=await supabaseClient.from(`profiles`).update({public_profile:on}).eq(`user_id`,currentUser.id).select().single();if(error){showToast(`Erreur de sauvegarde, réessaie`);console.error(error);return false}currentProfile=data;document.getElementById(`ppPublicToggle`).checked=on;renderProfileShareNote();showToast(on?`Profil partagé`:`Profil plus partagé`);return true}document.getElementById(`ppPublicToggle`).addEventListener(`change`,async e=>{const on=e.target.checked;if(!await savePublicProfile(on))e.target.checked=!on});document.getElementById(`ppCopyLinkBtn`).addEventListener(`click`,()=>{document.getElementById(`copyPublicProfileLink`).click()});function renderProfileShareNote(){const note=document.getElementById(`ppShareNote`);if(!note)return;const on=!!(currentProfile&&currentProfile.public_profile);note.textContent=on?`Ton profil est partagé. Pour arrêter : Paramètres, Confidentialité.`:`Ton profil sera partagé dès que tu copies le lien.`}function toggleProfileShareSheet(open){const sheet=document.getElementById(`ppShareSheet`);const show=typeof open===`boolean`?open:sheet.hidden;sheet.hidden=!show;document.getElementById(`ppShareBtn`).setAttribute(`aria-expanded`,String(show));if(show)renderProfileShareNote()}async function copyProfileShareLink(){if(!(currentProfile&&currentProfile.public_profile)){const ok=await savePublicProfile(true);if(!ok)return}try{await navigator.clipboard.writeText(publicProfileUrl());showToast(`Lien copié`)}catch(e){showToast(`Impossible de copier : `+publicProfileUrl());console.error(e)}renderProfileShareNote()}document.getElementById(`ppShareBtn`).addEventListener(`click`,()=>toggleProfileShareSheet());document.getElementById(`ppShareCloseBtn`).addEventListener(`click`,()=>toggleProfileShareSheet(false));document.getElementById(`ppShareCopyBtn`).addEventListener(`click`,copyProfileShareLink);